tape( 'the function quick returns when `M` or `N` is equal to 0', function test( t ) {
	var expectedTAUQ;
	var expectedTAUP;
	var expectedA;
	var expectedD;
	var expectedE;
	var expectedX;
	var expectedY;
	var data;
	var TAUP;
	var TAUQ;
	var A;
	var D;
	var E;
	var X;
	var Y;

	data = M_GT_N_ROW_MAJ;

	A = new Float64Array( data.A );
	D = new Float64Array( data.D );
	E = new Float64Array( data.E );
	TAUQ = new Float64Array( data.TAUQ );
	TAUP = new Float64Array( data.TAUP );
	X = new Float64Array( data.X );
	Y = new Float64Array( data.Y );

	expectedA = new Float64Array( data.A );
	expectedD = new Float64Array( data.D );
	expectedE = new Float64Array( data.E );
	expectedTAUQ = new Float64Array( data.TAUQ );
	expectedTAUP = new Float64Array( data.TAUP );
	expectedX = new Float64Array( data.X );
	expectedY = new Float64Array( data.Y );

	dlabrd( data.order, 0, 0, data.NB, A, data.LDA, D, E, TAUQ, TAUP, X, data.LDX, Y, data.LDY );
	t.strictEqual( isAlmostEqual( A, expectedA, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( D, expectedD, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( E, expectedE, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAUQ, expectedTAUQ, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAUP, expectedTAUP, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( X, expectedX, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Y, expectedY, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function reduces the first `NB` rows and columns of a general matrix to a bi-diagonal form (M >= N, row-major)', function test( t ) {
	var expectedTAUQ;
	var expectedTAUP;
	var expectedA;
	var expectedD;
	var expectedE;
	var expectedX;
	var expectedY;
	var data;
	var TAUP;
	var TAUQ;
	var A;
	var D;
	var E;
	var X;
	var Y;

	data = M_GT_N_ROW_MAJ;

	A = new Float64Array( data.A );
	D = new Float64Array( data.D );
	E = new Float64Array( data.E );
	TAUQ = new Float64Array( data.TAUQ );
	TAUP = new Float64Array( data.TAUP );
	X = new Float64Array( data.X );
	Y = new Float64Array( data.Y );

	expectedA = new Float64Array( data.A_out );
	expectedD = new Float64Array( data.D_out );
	expectedE = new Float64Array( data.E_out );
	expectedTAUQ = new Float64Array( data.TAUQ_out );
	expectedTAUP = new Float64Array( data.TAUP_out );
	expectedX = new Float64Array( data.X_out );
	expectedY = new Float64Array( data.Y_out );

	dlabrd( data.order, data.M, data.N, data.NB, A, data.LDA, D, E, TAUQ, TAUP, X, data.LDX, Y, data.LDY );
	t.strictEqual( isAlmostEqual( A, expectedA, 2 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( D, expectedD, 0 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( E, expectedE, 4 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAUQ, expectedTAUQ, 0 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( TAUP, expectedTAUP, 1 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( X, expectedX, 2 ), true, 'returns expected value' );
	t.strictEqual( isAlmostEqual( Y, expectedY, 0 ), true, 'returns expected value' );
	t.end();
});

